  "locked": "verrouillée",
  "Mission {n}: {name}. {status}.": "Mission {n} : {name}. {status}.",
  "Next: {region} · {n}/7": "Suivant : {region} · {n}/7",
  "Pass Sector {n} to unlock recon imagery": "Terminez le Secteur {n} pour débloquer l’image de reconnaissance",
  "Reconnaissance map": "Carte de reconnaissance",
  "Complete Sector {n} to decrypt tactical briefing and enemy roster.": "Terminez le Secteur {n} pour décrypter le briefing tactique et la composition ennemie.",
  "Italy": "Italie",
  "Alps": "Alpes",
  "Bohemia & Saxony": "Bohême et Saxe",
  "Germany": "Allemagne",
